        if spec.origin in {"namespace", None}:
            if import_name is not None and import_name != root_mod_name:
                # Find which namespace location contains the actual module
                # by looking at the sub-package's spec.
                child_spec = importlib.util.find_spec(import_name)
                if child_spec is not None:
                    if child_spec.submodule_search_locations:
                        # It's a package with __init__.py
                        child_path = child_spec.submodule_search_locations[0]
                    elif child_spec.origin:
