```python
def _find_package_path(root_mod_name, import_name=None):
    """Find the path that contains the package or module."""
    try:
        spec = importlib.util.find_spec(root_mod_name)

        if spec is None:
            raise ValueError("not found")
    except (ImportError, ValueError):
        pass
    else:
        # namespace package
        if spec.origin in {"namespace", None}:
            # If there is a more specific import name, try to find
            # which namespace location contains it.
            if import_name is not None and import_name != root_mod_name:
                package_spec = importlib.util.find_spec(import_name)
                if package_spec is not None:
                    # Find the path to the package/module
                    if package_spec.submodule_search_locations:
                        pkg_path = package_spec.submodule_search_locations[0]
                    elif package_spec.origin:
                        pkg_path = os.path.dirname(package_spec.origin)
                    else:
                        pkg_path = None

                    if pkg_path is not None:
                        for location in spec.submodule_search_locations:
                            if pkg_path.startswith(location):
                                return os.path.dirname(location)

            return os.path.dirname(next(iter(spec.submodule_search_locations)))
        # a package (with __init__.py)
        elif spec.submodule_search_locations:
            return os.path.dirname(os.path.dirname(spec.origin))
        # just a normal module
        else:
            return os.path.dirname(spec.origin)

    # ... rest of the function unchanged
```

